import numpy as np
def equation(eps, T, params):
    a,b,c,d,f,g,h,k,m,n = params[:10]
    num = a + b*T + c/T + (d + f*T + m/T)*eps
    return -eps*num*np.exp(-(g + h/T)*eps)/(1 + k*eps + n*eps**2)

import numpy as np
def equation(eps, T, params):
    a,c,d,f,g,h,m,p,q = params[:9]
    num = a + c/T + (d + f*T + m/T)*eps
    return -eps*num*np.exp(-(g + h/T + p*T)*eps - q*eps**2)
